atts.custom_css:
selector,selector:hover{color:rgb(44, 35, 23) !important;}
selector{text-transform:uppercase !important;letter-spacing:2.6px !important;font-size:10px !important;font-weight:400 !important;padding:0px 30px 0px 30px !important;}
selector{align-self:center;width:auto;}
:where(selector){background-image:linear-gradient(rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.52)), linear-gradient(135deg, rgba(0, 0, 0, 0.04), rgba(0, 0, 0, 0) 45%);line-height:15px;text-align:center;transition:transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.5s, background 0.4s;}
